-- Two-way Jira Cloud integration, per organization (supersedes the "Jira -- P3, not now"
-- deferral in docs/decisions/0025/0026/0074: the user explicitly asked for it).
--
-- ---------------------------------------------------------------------------
-- Auth model: one API token per organization, HackerOne/Bugcrowd style. An org admin
-- pastes their own Jira site URL + account email + API token (generated by that Jira user
-- at id.atlassian.com). No Atlassian Connect / OAuth 3LO app, no marketplace listing.
-- Unpatched calls Jira REST v3 with Basic auth (email:token) on that org's behalf.
--
-- Data flow:
--   OUT  report lifecycle RPCs already enqueue outbox_events (report.created/accepted/
--        resolved/... and report.message_posted). A new outbox consumer
--        (workers/outbox/handlers/jira/jira-sync-handler.ts) reads the credential through
--        get_jira_credentials (service_role only) at dispatch time -- the token is never in
--        an outbox payload -- and creates/transitions/comments on the Jira issue.
--   IN   Jira's admin webhook POSTs to /api/webhooks/jira/<organization_id>, signed with
--        X-Hub-Signature: sha256=HMAC(webhook_secret, raw body). The route re-derives the
--        HMAC with the secret stored here and compares in constant time. A verified
--        "issue moved to a Done-category status" then calls the EXISTING resolve_report RPC
--        as the connection's created_by user (withActorTransaction) -- no report business
--        logic is duplicated, and private.lock_and_authorize_report_for_triage still decides.
--
-- Secrets at rest: the API token AND the webhook secret both use the existing
-- private.encrypt_sensitive_field / decrypt_sensitive_field (pgcrypto pgp_sym_*, key from
-- app.settings.kyc_encryption_key -- 202609010004). No second scheme. The webhook secret
-- must be recoverable in plaintext (an HMAC needs the key itself; a hash cannot verify a
-- signature), so it is encrypted, not hashed. It is generated HERE, server-side, from
-- gen_random_bytes(32), and returned exactly once by create_jira_connection -- the same
-- "shown once" convention as personal access tokens. The token is only ever shown back as
-- its last 4 characters (api_token_last4, captured at write time so display never decrypts).
-- The encrypted columns are not granted to `authenticated` at all (column-level grant).
--
-- SSRF: site_url is constrained to https://<site>.atlassian.net -- the server sends a
-- credential to this URL, so an arbitrary host would let an org admin aim the worker at an
-- internal address. Jira Cloud sites live on atlassian.net (legacy *.jira.com sites are not
-- accepted -- disclosed limitation).
--
-- ---------------------------------------------------------------------------
-- Update vs delete+recreate (the one real design choice), and why:
--
-- update_jira_connection exists, but site_url is IMMUTABLE. Atlassian API tokens expire
-- (max one year), so rotating the token is routine -- forcing a disconnect for that would
-- drop every report->issue mapping and the next sync would create duplicate issues. So the
-- email/token/project/issue type are editable in place and the mappings survive. Changing
-- the SITE is different: every stored issue id/key belongs to the old site, so keeping the
-- mappings would point at the wrong Jira. That requires disconnect + reconnect, and
-- disconnect deletes the mappings (FK cascade). The webhook secret is not rotatable in place
-- for the same reason-of-simplicity: reconnecting issues a new one. Tradeoff accepted: a
-- site move re-creates issues for reports that are touched again afterwards.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 1. Tables.
-- ---------------------------------------------------------------------------

create table public.jira_connections (
  organization_id uuid primary key references public.organizations(id) on delete cascade,
  site_url text not null,
  account_email text not null,
  api_token_encrypted bytea not null,
  api_token_last4 text not null,
  webhook_secret_encrypted bytea not null,
  project_key text not null,
  issue_type_name text not null default 'Bug',
  -- The inbound webhook acts AS this user (it has no session of its own). Stored at
  -- creation; if this user later loses owner/security_admin/triager access or is
  -- deactivated, inbound status changes stop (the existing RPC authorization refuses them).
  created_by uuid not null references public.users(id),
  -- Last outbound failure, so an admin can see "token expired" without reading worker
  -- logs. Cleared on the next successful sync.
  last_error text,
  last_error_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint jira_connections_site_url_format check (site_url ~ '^https://[a-z0-9][a-z0-9-]{0,62}\.atlassian\.net$'),
  constraint jira_connections_email_format check (char_length(account_email) <= 254 and account_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  constraint jira_connections_project_key_format check (project_key ~ '^[A-Z][A-Z0-9_]{1,9}$'),
  constraint jira_connections_issue_type_len check (char_length(issue_type_name) between 1 and 60),
  constraint jira_connections_last4_len check (char_length(api_token_last4) <= 4)
);

alter table public.jira_connections enable row level security;
create policy "jira connections readable by org admins" on public.jira_connections
  for select to authenticated
  using (private.has_org_role(organization_id, array['owner', 'security_admin']::public.organization_member_role[]));
revoke all on public.jira_connections from anon, authenticated;
-- Column-level: the two bytea columns are not selectable by `authenticated` at all. Writes
-- only through the RPCs below.
grant select (organization_id, site_url, account_email, api_token_last4, project_key, issue_type_name, created_by, last_error, last_error_at, created_at, updated_at)
  on public.jira_connections to authenticated;
grant select, insert, update, delete on public.jira_connections to service_role;

create table public.report_jira_links (
  report_id uuid primary key references public.reports(id) on delete cascade,
  organization_id uuid not null references public.jira_connections(organization_id) on delete cascade,
  jira_issue_id text not null,
  jira_issue_key text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  last_synced_at timestamptz not null default now(),
  constraint report_jira_links_issue_id_format check (jira_issue_id ~ '^[0-9]{1,20}$'),
  constraint report_jira_links_issue_key_format check (jira_issue_key ~ '^[A-Z][A-Z0-9_]{1,9}-[0-9]{1,12}$'),
  constraint report_jira_links_issue_unique unique (organization_id, jira_issue_id)
);

-- No authenticated policy: staff read their link through get_report_jira_link (which
-- applies the triage predicate and builds the URL); the worker and webhook use service_role.
alter table public.report_jira_links enable row level security;
revoke all on public.report_jira_links from anon, authenticated;
grant select, insert, update, delete on public.report_jira_links to service_role;

-- ---------------------------------------------------------------------------
-- 2. Admin RPCs (authenticated; owner/security_admin, re-derived from auth.uid()).
-- ---------------------------------------------------------------------------

create or replace function private.validate_jira_connection_input(p_account_email text, p_api_token text, p_project_key text, p_issue_type_name text, p_token_required boolean)
returns void
language plpgsql immutable set search_path = ''
as $$
begin
  if p_account_email is null or char_length(p_account_email) > 254 or p_account_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'INVALID_JIRA_EMAIL: Enter the email address of the Jira account that owns the API token.' using errcode = '22023';
  end if;
  if p_token_required and (p_api_token is null or char_length(p_api_token) = 0) then
    raise exception 'INVALID_JIRA_TOKEN: Paste the Jira API token.' using errcode = '22023';
  end if;
  if p_api_token is not null and char_length(p_api_token) > 0 and (char_length(p_api_token) < 16 or char_length(p_api_token) > 512 or p_api_token ~ '\s') then
    raise exception 'INVALID_JIRA_TOKEN: That does not look like a Jira API token.' using errcode = '22023';
  end if;
  if p_project_key is null or p_project_key !~ '^[A-Z][A-Z0-9_]{1,9}$' then
    raise exception 'INVALID_JIRA_PROJECT: Use the project key as shown in Jira, e.g. SEC.' using errcode = '22023';
  end if;
  if p_issue_type_name is null or char_length(p_issue_type_name) not between 1 and 60 then
    raise exception 'INVALID_JIRA_ISSUE_TYPE: Enter an issue type name, e.g. Bug.' using errcode = '22023';
  end if;
end;
$$;

create or replace function public.create_jira_connection(target_org_id uuid, p_site_url text, p_account_email text, p_api_token text, p_project_key text, p_issue_type_name text)
returns table (webhook_secret text)
language plpgsql security definer set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  site text := lower(rtrim(trim(coalesce(p_site_url, '')), '/'));
  email text := trim(coalesce(p_account_email, ''));
  token text := trim(coalesce(p_api_token, ''));
  project text := upper(trim(coalesce(p_project_key, '')));
  issue_type text := trim(coalesce(p_issue_type_name, ''));
  secret text := encode(extensions.gen_random_bytes(32), 'hex');
begin
  if actor is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;
  if not private.has_org_role(target_org_id, array['owner', 'security_admin']::public.organization_member_role[]) then
    raise exception 'FORBIDDEN: only an owner or security admin can manage integrations' using errcode = '42501';
  end if;
  if site !~ '^https://[a-z0-9][a-z0-9-]{0,62}\.atlassian\.net$' then
    raise exception 'INVALID_JIRA_SITE: Use your Jira Cloud site address, e.g. https://yourcompany.atlassian.net' using errcode = '22023';
  end if;
  perform private.validate_jira_connection_input(email, token, project, issue_type, true);

  if exists (select 1 from public.jira_connections where organization_id = target_org_id) then
    raise exception 'JIRA_ALREADY_CONNECTED: Jira is already connected. Disconnect it first to connect a different site.' using errcode = '23505';
  end if;

  insert into public.jira_connections (organization_id, site_url, account_email, api_token_encrypted, api_token_last4, webhook_secret_encrypted, project_key, issue_type_name, created_by)
  values (target_org_id, site, email, private.encrypt_sensitive_field(token), right(token, 4), private.encrypt_sensitive_field(secret), project, issue_type, actor);

  -- Never the token or the secret in the audit trail.
  insert into public.audit_logs (actor_id, organization_id, action, entity_type, entity_id, metadata)
  values (actor, target_org_id, 'organization.jira_connected', 'organization', target_org_id,
    jsonb_build_object('site_url', site, 'project_key', project, 'issue_type_name', issue_type, 'account_email', email));

  return query select secret;
end;
$$;

revoke all on function public.create_jira_connection(uuid, text, text, text, text, text) from public;
grant execute on function public.create_jira_connection(uuid, text, text, text, text, text) to authenticated;

-- p_api_token null/empty keeps the current token (an edit that only changes the project).
create or replace function public.update_jira_connection(target_org_id uuid, p_account_email text, p_api_token text, p_project_key text, p_issue_type_name text)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  email text := trim(coalesce(p_account_email, ''));
  token text := nullif(trim(coalesce(p_api_token, '')), '');
  project text := upper(trim(coalesce(p_project_key, '')));
  issue_type text := trim(coalesce(p_issue_type_name, ''));
  previous public.jira_connections;
begin
  if actor is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;
  if not private.has_org_role(target_org_id, array['owner', 'security_admin']::public.organization_member_role[]) then
    raise exception 'FORBIDDEN: only an owner or security admin can manage integrations' using errcode = '42501';
  end if;
  perform private.validate_jira_connection_input(email, token, project, issue_type, false);

  select * into previous from public.jira_connections where organization_id = target_org_id for update;
  if previous.organization_id is null then
    raise exception 'JIRA_NOT_CONNECTED: Jira is not connected for this organization.' using errcode = 'P0002';
  end if;

  update public.jira_connections set
    account_email = email,
    api_token_encrypted = coalesce(private.encrypt_sensitive_field(token), api_token_encrypted),
    api_token_last4 = coalesce(right(token, 4), api_token_last4),
    project_key = project,
    issue_type_name = issue_type,
    -- New credentials deserve a clean slate; the next sync reports any new failure.
    last_error = case when token is not null then null else last_error end,
    last_error_at = case when token is not null then null else last_error_at end,
    updated_at = now()
  where organization_id = target_org_id;

  insert into public.audit_logs (actor_id, organization_id, action, entity_type, entity_id, metadata)
  values (actor, target_org_id, 'organization.jira_connection_updated', 'organization', target_org_id,
    jsonb_build_object('token_replaced', token is not null,
      'previous_project_key', previous.project_key, 'project_key', project,
      'previous_account_email', previous.account_email, 'account_email', email,
      'previous_issue_type_name', previous.issue_type_name, 'issue_type_name', issue_type));
end;
$$;

revoke all on function public.update_jira_connection(uuid, text, text, text, text) from public;
grant execute on function public.update_jira_connection(uuid, text, text, text, text) to authenticated;

create or replace function public.delete_jira_connection(target_org_id uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  removed public.jira_connections;
  link_count integer;
begin
  if actor is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;
  if not private.has_org_role(target_org_id, array['owner', 'security_admin']::public.organization_member_role[]) then
    raise exception 'FORBIDDEN: only an owner or security admin can manage integrations' using errcode = '42501';
  end if;

  select count(*) into link_count from public.report_jira_links where organization_id = target_org_id;
  delete from public.jira_connections where organization_id = target_org_id returning * into removed;
  if removed.organization_id is null then
    raise exception 'JIRA_NOT_CONNECTED: Jira is not connected for this organization.' using errcode = 'P0002';
  end if;

  insert into public.audit_logs (actor_id, organization_id, action, entity_type, entity_id, metadata)
  values (actor, target_org_id, 'organization.jira_disconnected', 'organization', target_org_id,
    jsonb_build_object('site_url', removed.site_url, 'project_key', removed.project_key, 'removed_issue_links', link_count));
end;
$$;

revoke all on function public.delete_jira_connection(uuid) from public;
grant execute on function public.delete_jira_connection(uuid) to authenticated;

-- Display read: masked. Zero rows = not connected.
create or replace function public.get_jira_connection_for_org(target_org_id uuid)
returns table (
  site_url text, account_email text, api_token_last4 text, project_key text, issue_type_name text,
  created_by_name text, created_at timestamptz, updated_at timestamptz,
  last_error text, last_error_at timestamptz, linked_issue_count bigint
)
language plpgsql stable security definer set search_path = ''
as $$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;
  if not private.has_org_role(target_org_id, array['owner', 'security_admin']::public.organization_member_role[]) then
    raise exception 'FORBIDDEN: only an owner or security admin can manage integrations' using errcode = '42501';
  end if;
  return query
    select c.site_url, c.account_email, c.api_token_last4, c.project_key, c.issue_type_name,
      u.display_name, c.created_at, c.updated_at, c.last_error, c.last_error_at,
      (select count(*) from public.report_jira_links l where l.organization_id = c.organization_id)
    from public.jira_connections c
    left join public.users u on u.id = c.created_by
    where c.organization_id = target_org_id;
end;
$$;

revoke all on function public.get_jira_connection_for_org(uuid) from public;
grant execute on function public.get_jira_connection_for_org(uuid) to authenticated;

-- Report detail page: same predicate as lock_and_authorize_report_for_triage (org admin or
-- assigned program triager/manager), but non-raising -- no row for anyone else, including
-- the submitting researcher (the org's internal tracker is not theirs to see).
create or replace function public.get_report_jira_link(target_report_id uuid)
returns table (jira_issue_key text, jira_issue_url text, last_synced_at timestamptz)
language plpgsql stable security definer set search_path = ''
as $$
declare
  report public.reports;
begin
  if auth.uid() is null then return; end if;
  select * into report from public.reports where id = target_report_id;
  if report.id is null then return; end if;
  if not (
    private.has_org_role(report.organization_id, array['owner', 'security_admin']::public.organization_member_role[])
    or private.is_program_triager(report.program_id)
  ) then
    return;
  end if;
  return query
    select l.jira_issue_key, c.site_url || '/browse/' || l.jira_issue_key, l.last_synced_at
    from public.report_jira_links l
    join public.jira_connections c on c.organization_id = l.organization_id
    where l.report_id = target_report_id;
end;
$$;

revoke all on function public.get_report_jira_link(uuid) from public;
grant execute on function public.get_report_jira_link(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Internal RPCs: service_role ONLY (outbox worker + webhook route). Never granted to
--    authenticated/anon -- same posture as check_client_error_rate_limit (202609250009) and
--    route_and_create_notifications.
-- ---------------------------------------------------------------------------

-- The only place the token/secret are decrypted. actor_active lets the webhook refuse to
-- act as a deactivated/suspended user (has_org_role checks membership, not deactivated_at).
create or replace function public.get_jira_credentials(target_org_id uuid)
returns table (
  site_url text, account_email text, api_token text, webhook_secret text,
  project_key text, issue_type_name text, created_by uuid, actor_active boolean
)
language sql stable security definer set search_path = ''
as $$
  select c.site_url, c.account_email, private.decrypt_sensitive_field(c.api_token_encrypted),
    private.decrypt_sensitive_field(c.webhook_secret_encrypted), c.project_key, c.issue_type_name,
    c.created_by, (u.deactivated_at is null and not coalesce(u.is_suspended, false))
  from public.jira_connections c
  join public.users u on u.id = c.created_by
  where c.organization_id = target_org_id;
$$;

revoke all on function public.get_jira_credentials(uuid) from public, anon, authenticated;
grant execute on function public.get_jira_credentials(uuid) to service_role;

-- Everything the outbound consumer needs to build/transition/comment, in one read. The
-- report's CURRENT status (not the event type) drives the transition, so out-of-order
-- event processing still converges on the right Jira state.
create or replace function public.get_report_for_jira_sync(target_report_id uuid, p_message_id uuid default null)
returns table (
  report_id uuid, organization_id uuid, program_id uuid, program_name text, title text, description text, impact text,
  status public.report_status, confirmed_severity public.report_severity, researcher_severity public.report_severity,
  weakness_type text, asset_type text, display_target text, submitted_at timestamptz,
  jira_issue_id text, jira_issue_key text,
  message_body text, message_author_context text, message_visibility text, message_author_name text
)
language sql stable security definer set search_path = ''
as $$
  select r.id, r.organization_id, r.program_id, p.name, r.title, r.description, r.impact,
    r.status, r.confirmed_severity, r.researcher_severity,
    r.weakness_type::text, r.asset_type::text, r.display_target, r.submitted_at,
    l.jira_issue_id, l.jira_issue_key,
    m.body, m.author_context::text, m.visibility::text, mu.display_name
  from public.reports r
  join public.programs p on p.id = r.program_id
  left join public.report_jira_links l on l.report_id = r.id
  left join public.report_messages m on m.id = p_message_id and m.report_id = r.id
  left join public.users mu on mu.id = m.author_id
  where r.id = target_report_id;
$$;

revoke all on function public.get_report_for_jira_sync(uuid, uuid) from public, anon, authenticated;
grant execute on function public.get_report_for_jira_sync(uuid, uuid) to service_role;

-- Upserts the mapping and stamps a successful sync (clearing the connection's last_error).
-- Organization is re-derived from the report row, never a parameter.
create or replace function public.record_report_jira_sync(target_report_id uuid, p_jira_issue_id text, p_jira_issue_key text)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  org uuid;
begin
  select organization_id into org from public.reports where id = target_report_id;
  if org is null then raise exception 'REPORT_NOT_FOUND: report not found' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.jira_connections where organization_id = org) then
    raise exception 'JIRA_NOT_CONNECTED: Jira is not connected for this organization.' using errcode = 'P0002';
  end if;

  insert into public.report_jira_links (report_id, organization_id, jira_issue_id, jira_issue_key)
  values (target_report_id, org, p_jira_issue_id, p_jira_issue_key)
  on conflict (report_id) do update set
    -- A key can change if the issue is moved between projects; the id cannot.
    jira_issue_key = excluded.jira_issue_key, last_synced_at = now(), updated_at = now();

  update public.jira_connections set last_error = null, last_error_at = null
    where organization_id = org and last_error is not null;
end;
$$;

revoke all on function public.record_report_jira_sync(uuid, text, text) from public, anon, authenticated;
grant execute on function public.record_report_jira_sync(uuid, text, text) to service_role;

create or replace function public.record_jira_sync_error(target_org_id uuid, p_error text)
returns void
language sql security definer set search_path = ''
as $$
  update public.jira_connections set last_error = left(p_error, 500), last_error_at = now()
    where organization_id = target_org_id;
$$;

revoke all on function public.record_jira_sync_error(uuid, text) from public, anon, authenticated;
grant execute on function public.record_jira_sync_error(uuid, text) to service_role;

-- Inbound lookup by Jira's immutable issue id (keys change when an issue moves projects).
create or replace function public.find_report_by_jira_issue(target_org_id uuid, p_jira_issue_id text)
returns table (report_id uuid, status public.report_status)
language sql stable security definer set search_path = ''
as $$
  select r.id, r.status
  from public.report_jira_links l
  join public.reports r on r.id = l.report_id
  where l.organization_id = target_org_id and l.jira_issue_id = p_jira_issue_id;
$$;

revoke all on function public.find_report_by_jira_issue(uuid, text) from public, anon, authenticated;
grant execute on function public.find_report_by_jira_issue(uuid, text) to service_role;

-- Per-organization bucket on the public webhook, consumed BEFORE signature verification so
-- unauthenticated floods are bounded too. Keyed by the path's organization id whether or
-- not it exists, so the limiter itself reveals nothing. Tradeoff: a flood against one org's
-- URL can delay that org's real deliveries -- Jira retries 429 up to five times, and a
-- legitimate burst rarely nears 300/min.
create or replace function public.check_jira_webhook_rate_limit(target_org_id uuid)
returns boolean
language plpgsql security definer set search_path = ''
as $$
begin
  return private.check_and_consume_rate_limit('jira_webhook:' || target_org_id::text, 300, 60);
end;
$$;

revoke all on function public.check_jira_webhook_rate_limit(uuid) from public, anon, authenticated;
grant execute on function public.check_jira_webhook_rate_limit(uuid) to service_role;
